## Code Example

```c
typedef struct {
  uint16_t id;      // 0..65535
  uint16_t gen;     // generation counter
  bool in_use;
} pid_slot;

// Global state (simplified)
pid_slot table[65536];
pthread_mutex_t pid_lock;

int alloc_pid(void) {
  pthread_mutex_lock(&pid_lock);
  for (uint32_t i = 1; i < 65536; i++) {
    if (!table[i].in_use) {
      table[i].in_use = true;
      table[i].gen++;
      int pid = (table[i].gen << 16) | i;
      pthread_mutex_unlock(&pid_lock);
      return pid;
    }
  }
  pthread_mutex_unlock(&pid_lock);
  return -1; // exhausted
}

void release_pid(uint32_t pid) {
  uint16_t idx = pid & 0xFFFF;
  pthread_mutex_lock(&pid_lock);
  table[idx].in_use = false;
  pthread_mutex_unlock(&pid_lock);
}
```

